use cybercore::control_plane::ControlPlaneWorkspace;

let workspace = ControlPlaneWorkspace::load(".cybercore/workspace.json")?;
workspace.validate()?;
println!("{} resources", workspace.resources.len());

use cybercore::control_plane::ResourceManifest;

fn validate_resource(resource: &ResourceManifest) -> Result<(), Box<dyn std::error::Error>> {
    resource.validate()?;
    Ok(())
}

use cybercore::theme::ThemeCatalog;

let catalog = ThemeCatalog::load()?;
let active = catalog.active_id();
println!("active theme: {active}");

.cc-noise-sweep { position: relative; isolation: isolate; overflow: hidden; }
.cc-noise-sweep::after { content: ""; position: absolute; inset: -50%; z-index: -1; opacity: .08; pointer-events: none; background: repeating-radial-gradient(circle at 20% 30%, var(--cc-accent) 0 1px, transparent 1px 4px); animation: cc-noise-drift 1.8s steps(4) infinite; }
@keyframes cc-noise-drift { 50% { transform: translate(4%, -3%) } }
@media (prefers-reduced-motion: reduce) { .cc-noise-sweep::after { animation: none; } }

.cc-signal-scan { position: relative; overflow: hidden; }
.cc-signal-scan::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, transparent, color-mix(in srgb, var(--cc-accent) 28%, transparent), transparent); transform: translateY(-100%); animation: cc-signal-scan 3.6s linear infinite; }
@keyframes cc-signal-scan { to { transform: translateY(100%); } }
@media (prefers-reduced-motion: reduce) { .cc-signal-scan::after { display: none; } }

.cc-corner-brackets { position: relative; }
